function setupFlashDrag(){const stage=$("#fs-stage"),label=$("#fs-preview-label");label.contentEditable="true";label.spellcheck=false;label.setAttribute("aria-label","Flash Screen text — click and type to edit");label.style.cursor="text";label.addEventListener("click",e=>{e.stopPropagation();label.focus()});label.addEventListener("input",()=>{startupConfig.label=label.textContent;$("#fs-label").value=label.textContent;$("#fs-status").textContent="Text update hua. Save Flash Settings dabao."});for(const el of [$("#fs-preview-logo"),label]){let start=null,moved=false;el.addEventListener("pointerdown",e=>{if(el.hidden||el===label)return;start={x:e.clientX,y:e.clientY};moved=false});el.addEventListener("pointermove",e=>{if(!start)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;if(!moved&&Math.hypot(dx,dy)<7)return;moved=true;const r=stage.getBoundingClientRect(),x=Math.max(3,Math.min(97,(e.clientX-r.left)/r.width*100)),y=Math.max(5,Math.min(95,(e.clientY-r.top)/r.height*100));el.style.left=x+"%";el.style.top=y+"%";const key=el===stage.querySelector("#fs-preview-logo")?"logo":"label";startupConfig[key+"X"]=Math.round(x*10)/10;startupConfig[key+"Y"]=Math.round(y*10)/10});const end=()=>{if(moved)$("#fs-status").textContent="Position update hui. Save Flash Settings dabao.";start=null};el.addEventListener("pointerup",end);el.addEventListener("pointercancel",end)}}/* Drag is handled once by bindFlashStageDrag; avoid competing pointer handlers. */
