$("#startup-master-switch").addEventListener("change",async e=>{const box=e.currentTarget,label=$("#startup-switch-status"),turnOn=box.checked;box.disabled=true;try{const ref=hubCloud.db.collection("siteConfig").doc("public"),snap=await ref.get(),old=snap.data()?.startupScreen||{};await ref.set({startupScreen:{...old,enabled:turnOn}},{merge:true});const verify=await ref.get();if(verify.data()?.startupScreen?.enabled!==turnOn)throw Error("Switch save verify nahi hua");startupEnabled=turnOn;startupConfig={...startupConfig,enabled:turnOn};label.textContent=turnOn?"PUBLIC · Flash Screen website par active hai.":"PRIVATE · Flash Screen website par band hai."}catch(err){box.checked=!turnOn;label.textContent="Save failed: "+err.message}finally{box.disabled=false}});
